def summarize(rows: list[dict[str, float]]) -> dict[str, float]:
    total = sum(r['amount'] for r in rows)
    n = len(rows)
    return {
        'total': total,
        'mean': total / n if n else 0.0,
        'max': max((r['amount'] for r in rows), default=0.0),
    }

